        /**
          * @default false
         */
        "groupInvalid"?: boolean;
        "groupName"?: string;
        /**
          * @default false
         */
        "groupRequired"?: boolean;
        /**
          * Help text under this option's label.
         */
        "hint"?: string;
        /**
          * @default false
         */
        "selected"?: boolean;
        /**
          * The value submitted when this option is chosen.
         */
